"use strict";(globalThis.webpackChunkgrc||=[]).push([[58612],{52593(e){e.exports=JSON.parse('{"advisors":["anthony-kougkas","xian-he-sun"],"bio":"Meng Tang was a PhD student in the Department of Computer Science at the Illinois Institute of Technology and a member of the Gnosis Research Center from 2021 to 2026, advised by Dr. Xian-He Sun and Dr. Anthony Kougkas. Her research covered workflow I/O optimization, dataflow analysis, and data lifecycles in HPC workflows. She developed DaYu (CLUSTER\'24) and led the PDSW\'25 S3 roofline and IPDPS\'26 dataflow characterization papers with PNNL.","image":"tang.webp","links":{"email":"mtang11@hawk.illinoistech.edu","github":"https://github.com/candiceT233","linkedin":"https://www.linkedin.com/in/meng-tang-86417a128/","scholar":"https://scholar.google.com/citations?user=KXC9NesAAAAJ","orcid":"https://orcid.org/0009-0003-5995-6947"},"name":"Meng Tang","researchInterests":["Distributed Storage","Workflow I/O","Dataflow Optimization","HPC Workflows"],"slug":"meng-tang","title":"PhD Student (2021 to 2026)","type":"researcher","joinedDate":"2021-08-01","leftDate":"2026-08-31","projects":["portus"]}')}}]);